class DancepadStickyFooter{constructor(element){this.footer=element;this.wrapper=element.querySelector('.dan-sticky-footer__wrapper');this.resizeObserver=null;this.updateHeight=this.updateHeight.bind(this);this.isReady=!!this.wrapper;this.resizeHandler=()=>this.updateHeight();if(this.isReady){this.init()}}
init(){this.updateHeight();if(typeof ResizeObserver!=='undefined'){this.resizeObserver=new ResizeObserver(()=>{this.updateHeight()});this.resizeObserver.observe(this.wrapper)}
window.addEventListener('resize',this.resizeHandler,{passive:true})}
updateHeight(){if(!this.footer||!this.wrapper)return;this.footer.style.height=`${this.wrapper.scrollHeight}px`}
destroy(){window.removeEventListener('resize',this.resizeHandler);if(this.resizeObserver){this.resizeObserver.disconnect();this.resizeObserver=null}
if(this.footer){this.footer.style.height=''}
this.footer=null;this.wrapper=null;this.isReady=false}
static destroyAll(){DancepadStickyFooter.instances.forEach(instance=>instance.destroy());DancepadStickyFooter.instances=[]}}
DancepadStickyFooter.instances=[];
function dancepad_sticky_footer(){DancepadStickyFooter.destroyAll();document.querySelectorAll('.dan-sticky-footer').forEach(element=>{const instance=new DancepadStickyFooter(element);if(instance.isReady){DancepadStickyFooter.instances.push(instance)}})}
